// 0.2.3 < 0.2.3b < 0.2.4: la letra es una corrección de esa versión
const cmpVer = (a, b) => { const p = (v) => { const m = String(v || '0').match(/^(\d+)(?:\.(\d+))?(?:\.(\d+))?([a-z]*)/) || []; return [+m[1] || 0, +m[2] || 0, +m[3] || 0, m[4] || '']; }; const x = p(a), y = p(b); for (let i = 0; i < 3; i++) { const d = x[i] - y[i]; if (d) return d; } return x[3] < y[3] ? -1 : x[3] > y[3] ? 1 : 0; };
// día y hora de publicación de cada versión (la hora, desde la 0.1.17; las de antes salen del historial de GitHub)
const fechaNov = (f, h) => { const d = deIso(f); return L(`${d.getDate()} ${MESES[d.getMonth()]} ${d.getFullYear()}${h ? `, ${h}` : ''}`, `${MESES_EN[d.getMonth()].slice(0, 3)} ${d.getDate()}, ${d.getFullYear()}${h ? `, ${h}` : ''}`); };

